select empno > ANY (
  select deptno from dept where emp.job = dept.name)
from emp;

select *
from emp e right join dept d
on e.deptno = d.deptno and e.empno = d.deptno;

select * from emp
where sal = 4
or empno NOT IN (select deptno from dept);

select * from dept as d
where EXISTS (
  select count(*) from emp e where d.deptno = e.deptno);

select name, deptno > ANY (
  select deptno from emp)
from dept;

select distinct d.deptno
from emp e
right outer join dept d on e.deptno = d.deptno;

with e2 as (
  select empno, case when true then deptno else null end as deptno
  from emp)
select empno,
  deptno in (select deptno from e2 where empno < 20) as d
from e2;

SELECT * 
FROM emp e1 
WHERE e1.empno > (SELECT MIN(deptno) FROM dept);

select empno, deptno, w_count from (
  select empno, deptno, count(empno) over (w) w_count
  from emp
  window w as (partition by deptno order by empno)
) sub_query where w_count is null;

SELECT "deptno", COUNT(DISTINCT "name")
FROM "dept"
GROUP BY "deptno";

SELECT sal, SUM(comm), MIN(comm), SUM(DISTINCT sal)
FROM emp
GROUP BY sal;

SELECT sal, SUM(comm), MIN(comm), sal::bigint AS sum
FROM emp
GROUP BY sal;

select coalesce(sum(count_comm), 0)
from (
  select deptno, count(comm) as count_comm
  from emp
  group by deptno, mgr) t;

